INSERT INTO books (id, title, author, cover_image, age_min, age_max, category_id, total_pages, is_master) VALUES (1, 'ライオンのルーくん', '田中はな', '/images/lion-cover.svg', 3, 5, 1, 5, 1);
INSERT INTO books (id, title, author, cover_image, age_min, age_max, category_id, total_pages, is_master) VALUES (2, 'おかあさんとぼく', '山田みこ', '/images/mother-cover.svg', 2, 4, 3, 5, 1);
INSERT INTO books (id, title, author, cover_image, age_min, age_max, category_id, total_pages, is_master) VALUES (3, 'ぶんぶんバス', '鈴木たろう', '/images/bus-cover.svg', 3, 6, 4, 5, 1);
INSERT INTO pages (book_id, page_number, image_path, text_content, is_master) VALUES (1, 1, '/images/lion-cover.svg', 'むかしむかし、大きな草原に、ルーくんというライオンの子どもが いました。', 1);
INSERT INTO pages (book_id, page_number, image_path, text_content, is_master) VALUES (1, 2, '/images/lion-cover.svg', 'ルーくんは毎朝、ほかのどうぶつたちに「おはようございます」と 元気よく あいさつしました。', 1);
INSERT INTO pages (book_id, page_number, image_path, text_content, is_master) VALUES (1, 3, '/images/lion-cover.svg', 'ある日、小さなうさぎが泣いていました。「どうしたの？」とルーくんが やさしく 聞きました。', 1);
INSERT INTO pages (book_id, page_number, image_path, text_content, is_master) VALUES (1, 4, '/images/lion-cover.svg', 'うさぎは「おうちへの道がわからなくなってしまったの」と言いました。ルーくんは「いっしょに探そう」と言いました。', 1);
INSERT INTO pages (book_id, page_number, image_path, text_content, is_master) VALUES (1, 5, '/images/lion-cover.svg', 'ふたりは力を合わせて、うさぎのおうちを見つけました。「ありがとう、ルーくん」。ルーくんはとても うれしい気持ちに なりました。おわり。', 1);
INSERT INTO pages (book_id, page_number, image_path, text_content, is_master) VALUES (2, 1, '/images/mother-cover.svg', 'ぼくのおかあさんは、世界でいちばんやさしいひとです。', 1);
INSERT INTO pages (book_id, page_number, image_path, text_content, is_master) VALUES (2, 2, '/images/mother-cover.svg', 'あさごはんのとき、おかあさんはいつもにこにこ笑っています。「たくさん食べてね」と言います。', 1);
INSERT INTO pages (book_id, page_number, image_path, text_content, is_master) VALUES (2, 3, '/images/mother-cover.svg', 'ぼくが転んで泣いたとき、おかあさんはすぐにとんできて、「だいじょうぶ？」とやさしく声をかけてくれました。', 1);
INSERT INTO pages (book_id, page_number, image_path, text_content, is_master) VALUES (2, 4, '/images/mother-cover.svg', 'よるになると、おかあさんはぼくに絵本を読んでくれます。おかあさんの声は、とても温かくてやさしいです。', 1);
INSERT INTO pages (book_id, page_number, image_path, text_content, is_master) VALUES (2, 5, '/images/mother-cover.svg', '「おかあさん、だいすき」とぼくが言うと、おかあさんはぎゅっとだきしめてくれました。「ぼくもだいすきよ」。おわり。', 1);
INSERT INTO pages (book_id, page_number, image_path, text_content, is_master) VALUES (3, 1, '/images/bus-cover.svg', 'まちの中を、大きな黄色いバスが走っています。名前は「ぶんぶん」といいます。', 1);
INSERT INTO pages (book_id, page_number, image_path, text_content, is_master) VALUES (3, 2, '/images/bus-cover.svg', 'ぶんぶんは朝早くから夜おそくまで、まちのひとたちを乗せて走ります。「ぶんぶん、ぶーん！」', 1);
INSERT INTO pages (book_id, page_number, image_path, text_content, is_master) VALUES (3, 3, '/images/bus-cover.svg', '今日はこうえんのまえで止まりました。小さな女の子がお母さんと手をつないで乗ってきました。', 1);
INSERT INTO pages (book_id, page_number, image_path, text_content, is_master) VALUES (3, 4, '/images/bus-cover.svg', '「つぎはえきまえです」ぶんぶんはみんなに知らせます。乗客たちは「ありがとう」と言ってバスをおります。', 1);
INSERT INTO pages (book_id, page_number, image_path, text_content, is_master) VALUES (3, 5, '/images/bus-cover.svg', '一日のおしごとを終えたぶんぶんは、車庫に帰ります。「また明日もみんなを乗せてはしるぞ！」おわり。', 1);
